window.GRADE9_QUESTION_BANK_DETAIL_SHARDS["details:SUBJECT-MATHEMATICS"]={"build_id":"sha256:9f4a13e75f9540091e0f0faa3770530d79ad7dd44c7b0fe8b93c6f4ea09edd2d","question_count":13,"questions":[{"answer":{"check":"Reconstruct OM=OR+RM=(a+b)/5, then subtract OP=a; the residual is PM=b/5-4a/5.","crux_move_ref":"PM = OM - OP,  OR = ⅕ a,  RM = ⅕ b ⇒ OM = OR + RM = ⅕ a + ⅕ b","reasoning":["Given: vector OP = a ⇒ R is on OP with OP = 5 OR ⇒ vector OR = ⅕ a.","Given: vector OQ = b with OQ = 5 RM ⇒ vector RM = ⅕ b.","Find position vector of M: vector OM = vector OR + vector RM = ⅕ a + ⅕ b.","Compute vector PM = vector OM - vector OP = (⅕ a + ⅕ b) - a.","Combine like terms: PM = (⅕ - 1) a + ⅕ b = -⅘ a + ⅕ b = ⅕ b - ⅘ a."],"reasoning_route":["Given: vector OP = a ⇒ R is on OP with OP = 5 OR ⇒ vector OR = ⅕ a.","Given: vector OQ = b with OQ = 5 RM ⇒ vector RM = ⅕ b.","Find position vector of M: vector OM = vector OR + vector RM = ⅕ a + ⅕ b.","Compute vector PM = vector OM - vector OP = (⅕ a + ⅕ b) - a.","Combine like terms: PM = (⅕ - 1) a + ⅕ b = -⅘ a + ⅕ b = ⅕ b - ⅘ a."],"summary":"A","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"Always track the origin of displacement vectors! Vector RM is relative to R, not O; OM = OR + RM.","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q01","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":161,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["Given: vector OP = a ⇒ R is on OP with OP = 5 OR ⇒ vector OR = ⅕ a.","Given: vector OQ = b with OQ = 5 RM ⇒ vector RM = ⅕ b.","Find position vector of M: vector OM = vector OR + vector RM = ⅕ a + ⅕ b.","Compute vector PM = vector OM - vector OP = (⅕ a + ⅕ b) - a.","Combine like terms: PM = (⅕ - 1) a + ⅕ b = -⅘ a + ⅕ b = ⅕ b - ⅘ a."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"PM = OM - OP,  OR = ⅕ a,  RM = ⅕ b ⇒ OM = OR + RM = ⅕ a + ⅕ b","status":"PUBLISHED","stem":"Let O be the origin, vector OP = a and vector OQ = b. If R is a point on OP such that OP = 5 OR, and M is a point such that OQ = 5 RM, then the vector PM expressed in terms of a and b is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2026"},{"answer":{"check":"Check |a+b|²=2+2cos60°=3, then independently expand the target dot product to -11/2.","crux_move_ref":"|a + b|² = |a|² + |b|² + 2(a · b) = 3 ⇒ 1 + 1 + 2(a · b) = 3 ⇒ a · b = ½","reasoning":["Given: |a| = 1, |b| = 1, and |a + b|² = 3.","Expand norm squared: |a + b|² = |a|² + |b|² + 2(a · b) = 1 + 1 + 2(a · b) = 2 + 2(a · b).","Set 2 + 2(a · b) = 3 ⇒ 2(a · b) = 1 ⇒ a · b = ½ (which corresponds to θ = 60°).","Expand target dot product:","E = (2a - 5b) · (3a + b) = 6|a|² + 2(a · b) - 15(a · b) - 5|b|².","E = 6(1) - 13(a · b) - 5(1) = 1 - 13(a · b).","Substitute a · b = ½: E = 1 - 13(½) = 1 - 6.5 = -5.5 = -11/2."],"reasoning_route":["Given: |a| = 1, |b| = 1, and |a + b|² = 3.","Expand norm squared: |a + b|² = |a|² + |b|² + 2(a · b) = 1 + 1 + 2(a · b) = 2 + 2(a · b).","Set 2 + 2(a · b) = 3 ⇒ 2(a · b) = 1 ⇒ a · b = ½ (which corresponds to θ = 60°).","Expand target dot product:","E = (2a - 5b) · (3a + b) = 6|a|² + 2(a · b) - 15(a · b) - 5|b|².","E = 6(1) - 13(a · b) - 5(1) = 1 - 13(a · b).","Substitute a · b = ½: E = 1 - 13(½) = 1 - 6.5 = -5.5 = -11/2."],"summary":"A","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"Do not treat vectors as scalars! The cross terms 2(a·b) - 15(b·a) combine to -13(a·b).","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q02","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":162,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["Given: |a| = 1, |b| = 1, and |a + b|² = 3.","Expand norm squared: |a + b|² = |a|² + |b|² + 2(a · b) = 1 + 1 + 2(a · b) = 2 + 2(a · b).","Set 2 + 2(a · b) = 3 ⇒ 2(a · b) = 1 ⇒ a · b = ½ (which corresponds to θ = 60°).","Expand target dot product:","E = (2a - 5b) · (3a + b) = 6|a|² + 2(a · b) - 15(a · b) - 5|b|².","E = 6(1) - 13(a · b) - 5(1) = 1 - 13(a · b).","Substitute a · b = ½: E = 1 - 13(½) = 1 - 6.5 = -5.5 = -11/2."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"|a + b|² = |a|² + |b|² + 2(a · b) = 3 ⇒ 1 + 1 + 2(a · b) = 3 ⇒ a · b = ½","status":"PUBLISHED","stem":"If a and b are unit vectors such that |a + b| = √3, then the value of (2a - 5b) · (3a + b) is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2025"},{"answer":{"check":"Verify cos²60°+cos²45°+cos²60°=1.","crux_move_ref":"cos² α + cos² β + cos² γ = 1","reasoning":["Direction cosines of unit vector u are: l = cos(π/3), m = cos(π/4), n = cos θ.","We have l = ½, m = 1/√2, n = cos θ.","Apply fundamental identity: l² + m² + n² = 1.","(½)² + (1/√2)² + cos² θ = 1 ⇒ ¼ + ½ + cos² θ = 1.","¾ + cos² θ = 1 ⇒ cos² θ = ¼.","Since θ is an acute angle: cos θ = +½ ⇒ θ = π/3 (60°)."],"reasoning_route":["Direction cosines of unit vector u are: l = cos(π/3), m = cos(π/4), n = cos θ.","We have l = ½, m = 1/√2, n = cos θ.","Apply fundamental identity: l² + m² + n² = 1.","(½)² + (1/√2)² + cos² θ = 1 ⇒ ¼ + ½ + cos² θ = 1.","¾ + cos² θ = 1 ⇒ cos² θ = ¼.","Since θ is an acute angle: cos θ = +½ ⇒ θ = π/3 (60°)."],"summary":"B","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"Direction cosines satisfy cos²α + cos²β + cos²γ = 1 (sum of squares = 1, NOT sum of angles = 180°!).","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q03","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":163,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["Direction cosines of unit vector u are: l = cos(π/3), m = cos(π/4), n = cos θ.","We have l = ½, m = 1/√2, n = cos θ.","Apply fundamental identity: l² + m² + n² = 1.","(½)² + (1/√2)² + cos² θ = 1 ⇒ ¼ + ½ + cos² θ = 1.","¾ + cos² θ = 1 ⇒ cos² θ = ¼.","Since θ is an acute angle: cos θ = +½ ⇒ θ = π/3 (60°)."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"cos² α + cos² β + cos² γ = 1","status":"PUBLISHED","stem":"If a unit vector u makes angles π/3 with i, π/4 with j, and an acute angle θ with k, then the value of θ is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2024"},{"answer":{"check":"After computing a⊥=(8,5,1)/3, dot it with b=(1,-2,2): (8-10+2)/3=0.","crux_move_ref":"a_perp = a - a_parallel = a - [(a · b) / |b|²] b","reasoning":["Compute dot product: a · b = (2)(1) + (3)(-2) + (-1)(2) = 2 - 6 - 2 = -6.","Compute magnitude squared |b|² = 1² + (-2)² + 2² = 1 + 4 + 4 = 9.","Parallel projection along b: a_parallel = [(a · b) / |b|²] b = (-6 / 9) b = -⅔ (i - 2j + 2k).","Perpendicular rejection: a_perp = a - a_parallel = (2i + 3j - k) - (-⅔ i + ⁴/₃ j - ⁴/₃ k).","x-component: 2 + ⅔ = ⁸/₃.","y-component: 3 - ⁴/₃ = ⁵/₃.","z-component: -1 + ⁴/₃ = +⅓.","Combine: a_perp = ⅓ (8i + 5j + k)."],"reasoning_route":["Compute dot product: a · b = (2)(1) + (3)(-2) + (-1)(2) = 2 - 6 - 2 = -6.","Compute magnitude squared |b|² = 1² + (-2)² + 2² = 1 + 4 + 4 = 9.","Parallel projection along b: a_parallel = [(a · b) / |b|²] b = (-6 / 9) b = -⅔ (i - 2j + 2k).","Perpendicular rejection: a_perp = a - a_parallel = (2i + 3j - k) - (-⅔ i + ⁴/₃ j - ⁴/₃ k).","x-component: 2 + ⅔ = ⁸/₃.","y-component: 3 - ⁴/₃ = ⁵/₃.","z-component: -1 + ⁴/₃ = +⅓.","Combine: a_perp = ⅓ (8i + 5j + k)."],"summary":"A","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"Remember a_perp = a - a_parallel! Verify orthogonality: (8)(1) + (5)(-2) + (1)(2) = 8 - 10 + 2 = 0.","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q04","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":164,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["Compute dot product: a · b = (2)(1) + (3)(-2) + (-1)(2) = 2 - 6 - 2 = -6.","Compute magnitude squared |b|² = 1² + (-2)² + 2² = 1 + 4 + 4 = 9.","Parallel projection along b: a_parallel = [(a · b) / |b|²] b = (-6 / 9) b = -⅔ (i - 2j + 2k).","Perpendicular rejection: a_perp = a - a_parallel = (2i + 3j - k) - (-⅔ i + ⁴/₃ j - ⁴/₃ k).","x-component: 2 + ⅔ = ⁸/₃.","y-component: 3 - ⁴/₃ = ⁵/₃.","z-component: -1 + ⁴/₃ = +⅓.","Combine: a_perp = ⅓ (8i + 5j + k)."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"a_perp = a - a_parallel = a - [(a · b) / |b|²] b","status":"PUBLISHED","stem":"Let a = 2i + 3j - k and b = i - 2j + 2k. The vector component of a orthogonal (perpendicular) to b is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2026"},{"answer":{"check":"Square both norms: equality cancels |a|² and |b|² and leaves 4a·b=0.","crux_move_ref":"|a + b|² = |a - b|² ⇔ 4(a · b) = 0 ⇔ a ⊥ b","reasoning":["Square both sides: |a + b|² = |a - b|².","Expand LHS: |a|² + |b|² + 2(a · b).","Expand RHS: |a|² + |b|² - 2(a · b).","Equate and cancel norms: 2(a · b) = -2(a · b) ⇒ 4(a · b) = 0.","Since a and b are non-zero: a · b = 0 ⇒ cos θ = 0 ⇒ θ = 90° (π/2 radians)."],"reasoning_route":["Square both sides: |a + b|² = |a - b|².","Expand LHS: |a|² + |b|² + 2(a · b).","Expand RHS: |a|² + |b|² - 2(a · b).","Equate and cancel norms: 2(a · b) = -2(a · b) ⇒ 4(a · b) = 0.","Since a and b are non-zero: a · b = 0 ⇒ cos θ = 0 ⇒ θ = 90° (π/2 radians)."],"summary":"C","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"A parallelogram has equal diagonals if and only if it is a rectangle (vectors are orthogonal)!","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q05","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":165,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["Square both sides: |a + b|² = |a - b|².","Expand LHS: |a|² + |b|² + 2(a · b).","Expand RHS: |a|² + |b|² - 2(a · b).","Equate and cancel norms: 2(a · b) = -2(a · b) ⇒ 4(a · b) = 0.","Since a and b are non-zero: a · b = 0 ⇒ cos θ = 0 ⇒ θ = 90° (π/2 radians)."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"|a + b|² = |a - b|² ⇔ 4(a · b) = 0 ⇔ a ⊥ b","status":"PUBLISHED","stem":"Let a and b be two non-zero vectors such that |a + b| = |a - b|. The angle between a and b is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2025"},{"answer":{"check":"Expand (2a+3b)×(a-b)=-5a×b and verify |a×b|=12√2; half its magnitude is 30√2.","crux_move_ref":"Area = ½ |(2a + 3b) × (a - b)| = ⁵/₂ |a × b|","reasoning":["Let u = 2a + 3b and v = a - b.","Expand cross product: u × v = -2(a × b) + 3(b × a) = -5(a × b).","Area of triangle = ½ |u × v| = ⁵/₂ |a × b|.","Compute a × b = 0i + 12j - 12k ⇒ |a × b| = √(144 + 144) = 12√2.","Area of triangle = ⁵/₂ (12√2) = 30√2.","Square of area = (30√2)² = 900 × 2 = 1800."],"reasoning_route":["Let u = 2a + 3b and v = a - b.","Expand cross product: u × v = -2(a × b) + 3(b × a) = -5(a × b).","Area of triangle = ½ |u × v| = ⁵/₂ |a × b|.","Compute a × b = 0i + 12j - 12k ⇒ |a × b| = √(144 + 144) = 12√2.","Area of triangle = ⁵/₂ (12√2) = 30√2.","Square of area = (30√2)² = 900 × 2 = 1800."],"summary":"D","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"Cross product is anti-commutative: 3(b × a) = -3(a × b), so the coefficients add to -5, not +1!","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q06","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":166,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["Let u = 2a + 3b and v = a - b.","Expand cross product: u × v = -2(a × b) + 3(b × a) = -5(a × b).","Area of triangle = ½ |u × v| = ⁵/₂ |a × b|.","Compute a × b = 0i + 12j - 12k ⇒ |a × b| = √(144 + 144) = 12√2.","Area of triangle = ⁵/₂ (12√2) = 30√2.","Square of area = (30√2)² = 900 × 2 = 1800."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"Area = ½ |(2a + 3b) × (a - b)| = ⁵/₂ |a × b|","status":"PUBLISHED","stem":"Let a = 2i + 3j + 3k and b = 6i + 3j + 3k. The square of the area of the triangle with adjacent sides determined by vectors (2a + 3b) and (a - b) is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2026"},{"answer":{"check":"Compute d1×d2=(-2,-14,-10), whose magnitude is 10√3; halve it to obtain 5√3.","crux_move_ref":"Area of Parallelogram with Diagonals = ½ |d₁ × d₂|","reasoning":["When diagonals are given, Area = ½ |d₁ × d₂|.","Compute d₁ × d₂ = -2i - 14j - 10k.","Magnitude: |d₁ × d₂| = √(4 + 196 + 100) = √300 = 10√3.","Area = ½ (10√3) = 5√3."],"reasoning_route":["When diagonals are given, Area = ½ |d₁ × d₂|.","Compute d₁ × d₂ = -2i - 14j - 10k.","Magnitude: |d₁ × d₂| = √(4 + 196 + 100) = √300 = 10√3.","Area = ½ (10√3) = 5√3."],"summary":"A","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"When diagonals are given, always multiply by ½! The formula Area = |a × b| applies ONLY when a and b are adjacent sides.","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q07","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":167,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["When diagonals are given, Area = ½ |d₁ × d₂|.","Compute d₁ × d₂ = -2i - 14j - 10k.","Magnitude: |d₁ × d₂| = √(4 + 196 + 100) = √300 = 10√3.","Area = ½ (10√3) = 5√3."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"Area of Parallelogram with Diagonals = ½ |d₁ × d₂|","status":"PUBLISHED","stem":"The diagonals of a parallelogram are given by vectors d₁ = 3i + j - 2k and d₂ = i - 3j + 4k. The area of the parallelogram is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2026"},{"answer":{"check":"Residual check: 16²+12²=256+144=400=(10²)(2²).","crux_move_ref":"Lagrange's Identity: |a × b|² + (a · b)² = |a|² |b|²","reasoning":["Apply Lagrange's Identity: |a × b|² = |a|² |b|² - (a · b)².","Substitute values: |a|² = 10² = 100, |b|² = 2² = 4.","Product of squared norms: |a|² |b|² = 100 × 4 = 400.","Squared dot product: (a · b)² = 12² = 144.","|a × b|² = 400 - 144 = 256.","Take square root: |a × b| = √256 = 16."],"reasoning_route":["Apply Lagrange's Identity: |a × b|² = |a|² |b|² - (a · b)².","Substitute values: |a|² = 10² = 100, |b|² = 2² = 4.","Product of squared norms: |a|² |b|² = 100 × 4 = 400.","Squared dot product: (a · b)² = 12² = 144.","|a × b|² = 400 - 144 = 256.","Take square root: |a × b| = √256 = 16."],"summary":"A","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"Lagrange's Identity is instantaneous and avoids converting back and forth through trigonometric angles: |a×b|² + (a·b)² ≡ |a|²|b|²!","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q08","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":168,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["Apply Lagrange's Identity: |a × b|² = |a|² |b|² - (a · b)².","Substitute values: |a|² = 10² = 100, |b|² = 2² = 4.","Product of squared norms: |a|² |b|² = 100 × 4 = 400.","Squared dot product: (a · b)² = 12² = 144.","|a × b|² = 400 - 144 = 256.","Take square root: |a × b| = √256 = 16."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"Lagrange's Identity: |a × b|² + (a · b)² = |a|² |b|²","status":"PUBLISHED","stem":"For any two vectors a and b, if |a| = 10, |b| = 2, and a · b = 12, then the magnitude of the cross product |a × b| is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2024"},{"answer":{"check":"Substitute each root into (μ-1)²(μ+2): μ=1 and μ=-2 both give zero determinant.","crux_move_ref":"Coplanarity ⇔ det([[μ,1,1],[1,μ,1],[1,1,μ]]) = 0 = (μ-1)²(μ+2)","reasoning":["Three vectors are coplanar exactly when their scalar triple product is zero.","Form the determinant det([[μ,1,1],[1,μ,1],[1,1,μ]]).","Expanding gives μ³ - 3μ + 2 = 0.","Factor: μ³ - 3μ + 2 = (μ - 1)²(μ + 2).","The distinct real values are μ = 1 and μ = -2.","Their sum is 1 + (-2) = -1."],"reasoning_route":["Three vectors are coplanar exactly when their scalar triple product is zero.","Form the determinant det([[μ,1,1],[1,μ,1],[1,1,μ]]).","Expanding gives μ³ - 3μ + 2 = 0.","Factor: μ³ - 3μ + 2 = (μ - 1)²(μ + 2).","The distinct real values are μ = 1 and μ = -2.","Their sum is 1 + (-2) = -1."],"summary":"A","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"Zero scalar triple product means zero spanned volume/coplanarity; repeated roots still count once when the question asks for distinct real values.","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q09","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":169,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["Three vectors are coplanar exactly when their scalar triple product is zero.","Form the determinant det([[μ,1,1],[1,μ,1],[1,1,μ]]).","Expanding gives μ³ - 3μ + 2 = 0.","Factor: μ³ - 3μ + 2 = (μ - 1)²(μ + 2).","The distinct real values are μ = 1 and μ = -2.","Their sum is 1 + (-2) = -1."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"Coplanarity ⇔ det([[μ,1,1],[1,μ,1],[1,1,μ]]) = 0 = (μ-1)²(μ+2)","status":"PUBLISHED","stem":"If the vectors μi + j + k, i + μj + k and i + j + μk are coplanar, then the sum of the distinct real values of μ is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2019"},{"answer":{"check":"Direct determinant check gives -7; geometric volume is its absolute value, 7.","crux_move_ref":"Volume V = | [a b c] | = | det(a, b, c) |","reasoning":["Set up determinant of coordinate matrix: det = 2(3) - (-3)(5) + 4(-7) = 6 + 15 - 28 = -7.","Volume is absolute value: V = |-7| = 7 cubic units."],"reasoning_route":["Set up determinant of coordinate matrix: det = 2(3) - (-3)(5) + 4(-7) = 6 + 15 - 28 = -7.","Volume is absolute value: V = |-7| = 7 cubic units."],"summary":"A","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"Volume must be positive; always take the absolute value of the determinant!","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q10","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":170,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["Set up determinant of coordinate matrix: det = 2(3) - (-3)(5) + 4(-7) = 6 + 15 - 28 = -7.","Volume is absolute value: V = |-7| = 7 cubic units."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"Volume V = | [a b c] | = | det(a, b, c) |","status":"PUBLISHED","stem":"The volume of the parallelepiped whose coterminous edges are represented by vectors a = 2i - 3j + 4k, b = i + 2j - k, and c = 3i - j + 2k is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2024"},{"answer":{"check":"Substitute λ=1/9 into r=b+λa and verify both residuals: (r-b)×a=0 and r·a=0; then |3r|²=44.","crux_move_ref":"r × a + a × b = 0 ⇔ (r - b) × a = 0 ⇔ r - b = λ a ⇔ r = b + λ a","reasoning":["Rewrite r × a + a × b = 0 using a × b = -(b × a): (r - b) × a = 0.","Therefore r - b is parallel to a, so r = b + λa.","Use r · a = 0: (b + λa) · a = 0, hence λ = -(a · b)/|a|².","Here |a|² = 7 + 1 + 1 = 9 and a · b = (1)(1) + (-1)(2) = -1, so λ = 1/9.","Then |r|² = |b|² + 2λ(a · b) + λ²|a|² = 5 - 2/9 + 1/9 = 44/9.","Therefore |3r|² = 9|r|² = 44."],"reasoning_route":["Rewrite r × a + a × b = 0 using a × b = -(b × a): (r - b) × a = 0.","Therefore r - b is parallel to a, so r = b + λa.","Use r · a = 0: (b + λa) · a = 0, hence λ = -(a · b)/|a|².","Here |a|² = 7 + 1 + 1 = 9 and a · b = (1)(1) + (-1)(2) = -1, so λ = 1/9.","Then |r|² = |b|² + 2λ(a · b) + λ²|a|² = 5 - 2/9 + 1/9 = 44/9.","Therefore |3r|² = 9|r|² = 44."],"summary":"A","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"Never attempt to 'divide' by vector a! Factor (r - b) × a = 0 into collinear line r = b + λ a.","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q11","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":171,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["Rewrite r × a + a × b = 0 using a × b = -(b × a): (r - b) × a = 0.","Therefore r - b is parallel to a, so r = b + λa.","Use r · a = 0: (b + λa) · a = 0, hence λ = -(a · b)/|a|².","Here |a|² = 7 + 1 + 1 = 9 and a · b = (1)(1) + (-1)(2) = -1, so λ = 1/9.","Then |r|² = |b|² + 2λ(a · b) + λ²|a|² = 5 - 2/9 + 1/9 = 44/9.","Therefore |3r|² = 9|r|² = 44."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"r × a + a × b = 0 ⇔ (r - b) × a = 0 ⇔ r - b = λ a ⇔ r = b + λ a","status":"PUBLISHED","stem":"Let a = √7 i + j - k and b = j + 2k. If r is a vector such that r × a + a × b = 0 and r · a = 0, then the value of |3r|² is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2026"},{"answer":{"check":"BAC-CAB gives coefficients along independent b and c: a·c=1/2 and a·b=0; unit vectors imply θac=60°.","crux_move_ref":"a × (b × c) = (a · c) b - (a · b) c = ½ b + 0 c","reasoning":["Apply BAC-CAB identity: a × (b × c) = (a · c) b - (a · b) c.","Equating components along non-coplanar vectors b and c gives a · c = ½.","Since a and c are unit vectors: cos θ = ½ ⇒ θ = 60°."],"reasoning_route":["Apply BAC-CAB identity: a × (b × c) = (a · c) b - (a · b) c.","Equating components along non-coplanar vectors b and c gives a · c = ½.","Since a and c are unit vectors: cos θ = ½ ⇒ θ = 60°."],"summary":"C","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"Cross product is NOT associative: a × (b × c) lies in the plane of b and c, while (a × b) × c lies in the plane of a and b!","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q12","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":172,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["Apply BAC-CAB identity: a × (b × c) = (a · c) b - (a · b) c.","Equating components along non-coplanar vectors b and c gives a · c = ½.","Since a and c are unit vectors: cos θ = ½ ⇒ θ = 60°."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"a × (b × c) = (a · c) b - (a · b) c = ½ b + 0 c","status":"PUBLISHED","stem":"For any three vectors a, b, c, the vector triple product a × (b × c) is equal to (a · c) b - (a · b) c. If a × (b × c) = ½ b, where a, b, c are non-coplanar unit vectors, the angle between a and c is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2024"},{"answer":{"check":"Use n=b1×b2=(-1,2,-1), then project a2-a1=(1,2,2) onto n: |1|/√6.","crux_move_ref":"d = | (a₂ - a₁) · (b₁ × b₂) | / | b₁ × b₂ |","reasoning":["a₂ - a₁ = i + 2j + 2k.","b₁ × b₂ = -i + 2j - k ⇒ |b₁ × b₂| = √6.","(a₂ - a₁) · (b₁ × b₂) = (1)(-1) + (2)(2) + (2)(-1) = 1.","Shortest distance d = 1 / √6."],"reasoning_route":["a₂ - a₁ = i + 2j + 2k.","b₁ × b₂ = -i + 2j - k ⇒ |b₁ × b₂| = √6.","(a₂ - a₁) · (b₁ × b₂) = (1)(-1) + (2)(2) + (2)(-1) = 1.","Shortest distance d = 1 / √6."],"summary":"A","verification_status":"VERIFIED_DIAGNOSTIC"},"answer_key_url":null,"authority_class":"CORPUS_SNAPSHOT","common_wrong_route":"Shortest distance between skew lines is the projection of the connector vector onto the common normal unit vector!","conditions":[],"difficulty":{"band":"D1","basis":"Diagnostic problem from Vector Algebra","components":{"algebra_computational_load":1,"concept_model_selection":1,"reasoning_chain_length":1,"representation_translation":1,"trap_exception_sensitivity":0},"score":2},"exam":"IIT-JEE Diagnostic","expected_time_seconds":90,"family_ref":"FAM-MATH-VECTORS","id":"VEC-Q13","last_checked":"2026-09-20","math_spans":[],"options":["[object Object]","[object Object]","[object Object]","[object Object]"],"order":173,"origin":"DIAGNOSTIC_HUB","paper":"Diagnostic Hub","paper_url":"","primary_capability_ref":"CAP-MATH-VECTORS","provenance_class":"EXAM_CORPUS_SNAPSHOT","question_number":"1","question_type":"single_correct_mcq","scaffolds":[],"secondary_capability_refs":[],"source_hints":["a₂ - a₁ = i + 2j + 2k.","b₁ × b₂ = -i + 2j - k ⇒ |b₁ × b₂| = √6.","(a₂ - a₁) · (b₁ × b₂) = (1)(-1) + (2)(2) + (2)(-1) = 1.","Shortest distance d = 1 / √6."],"source_path":"public/mathematics/vectors/explorers/vector_algebra/index.html","source_status":"PYQ_AUTHENTIC_DIAGNOSTIC","stable_crux_move":"d = | (a₂ - a₁) · (b₁ × b₂) | / | b₁ × b₂ |","status":"PUBLISHED","stem":"The shortest distance between the two skew lines r₁ = (i + 2j + 3k) + λ (2i + 3j + 4k) and r₂ = (2i + 4j + 5k) + μ (3i + 4j + 5k) is:","subject":"Mathematics","subject_ref":"SUBJECT-MATHEMATICS","subparts":[],"subtopic_refs":["CAP-MATH-VECTORS"],"topic":"Vector Algebra","topic_ref":"TOPIC-MATHEMATICS-VECTOR-ALGEBRA","version":"0.1.0","visual_ref":null,"wording_custody":"FAITHFUL_DIAGNOSTIC","year":"2025"}],"schema_version":"grade9v3-question-bank-detail-shard-v1","shard_id":"details:SUBJECT-MATHEMATICS","subject_ref":"SUBJECT-MATHEMATICS"};
